"""Model for the generated referral report."""

from pydantic import BaseModel, Field

from .needs import Discrepancy
from .referral import Recommendation

# Shown verbatim on every report: this is a decision-support draft, never an
# actioned referral, so the human-review requirement is stated explicitly.
HUMAN_REVIEW_STATEMENT = (
    "This report was generated by an AI decision-support tool. It must be "
    "reviewed and approved by a care coordinator before any referrals are "
    "actioned. It does not replace professional judgement."
)


class ReferralReport(BaseModel):
    """Structured referral report for a care coordinator to review."""

    patient_summary: str
    identified_needs: list[str] = Field(default_factory=list)
    discrepancies: list[Discrepancy] = Field(default_factory=list)
    recommended_services: list[Recommendation] = Field(default_factory=list)
    flagged_risks: list[str] = Field(default_factory=list)
    clinical_context_referenced: str = ""
    family_context_referenced: str = ""
    human_review_statement: str = HUMAN_REVIEW_STATEMENT
    # Plain-text rendering for display or future PDF export.
    text_version: str = ""
